import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:hive_flutter/hive_flutter.dart';
import '../../../application/itqan_journey_provider.dart';
import '../../../data/journey_content_repository.dart';
import '../../../quran/services/quran_service.dart';
import '../../../quran/models/ayah.dart';
import '../../../quran/models/surah.dart';
import '../../../shared/journey_quran_repository.dart';

class QuranJourneyScreen extends ConsumerStatefulWidget{const QuranJourneyScreen({super.key});@override ConsumerState<QuranJourneyScreen> createState()=>_QuranJourneyScreenState();}
class _QuranJourneyScreenState extends ConsumerState<QuranJourneyScreen>{final _repository=JourneyQuranRepository();final _service=QuranService();List<Surah> _surahs=[];List<Ayah> _ayahs=[];int _surah=1,_startAyah=1;bool _loading=true,_saving=false;@override void initState(){super.initState();_initialize();}Future<void> _initialize()async{try{_surahs=await _repository.surahs();_surah=await _repository.lastSurah();_startAyah=await _repository.lastAyah();_ayahs=await _repository.ayahs(_surah);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر تحميل المصحف: $e')));}finally{if(mounted)setState(()=>_loading=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('قرآن الرحلة')),body:_loading?const Center(child:CircularProgressIndicator()):Column(children:[Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:DropdownButton<int>(isExpanded:true,value:_surah,items:_surahs.map((s)=>DropdownMenuItem(value:s.number,child:Text('${s.number}. ${s.nameArabic}'))).toList(),onChanged:(v){if(v!=null)_selectSurah(v);})),const SizedBox(width:8),DropdownButton<int>(value:_startAyah.clamp(1,_ayahs.length),items:List.generate(_ayahs.length,(i)=>DropdownMenuItem(value:i+1,child:Text('آية ${i+1}'))),onChanged:(v){if(v!=null)setState(()=>_startAyah=v);})])),Expanded(child:ListView.builder(itemCount:_ayahs.length,itemBuilder:(context,i){if(i+1<_startAyah)return const SizedBox.shrink();return ListTile(leading:Text('${i+1}'),title:Text(_ayahs[i].textUthmani,textDirection:TextDirection.rtl,style:Theme.of(context).textTheme.headlineSmall),onTap:()=>_save(i+1));})),Padding(padding:const EdgeInsets.all(16),child:FilledButton(onPressed:_saving?null:()=>_recordRead(),child:Text(_saving?'جارٍ التسجيل':'تسجيل إنجاز القراءة')))]));Future<void> _selectSurah(int n)async{setState(()=>_loading=true);try{final rows=await _repository.ayahs(n);setState((){_surah=n;_ayahs=rows;_startAyah=1;});await _repository.savePosition(n,1);}finally{if(mounted)setState(()=>_loading=false);}}Future<void> _save(int ayah)async{setState(()=>_startAyah=ayah);await _repository.savePosition(_surah,ayah);}Future<void> _recordRead()async{setState(()=>_saving=true);try{await _repository.savePosition(_surah,_startAyah);final result=await ref.read(itqanJourneyProvider.notifier).recordActivity('quran.reading',metadata:{'pages':1});if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تم قبول القراءة • ${result['data']?['xp_earned']??0} XP')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('لم يقبل الخادم النشاط: $e')));}finally{if(mounted)setState(()=>_saving=false);}}
}
